pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(v[i] > 0);
        }
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool allSuccess = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool s, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v[i]));
            if (!s) { allSuccess = false; break; }
        }
        if (!allSuccess) {
            vm.assume(false);
        }
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // 1. Admissible domain: arrays must have same length; lengths must be > 0 (required by contract). Also at least one element.
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // 2. The external calls go to caddress. When caddress has code that succeeds on every call, the reference returns true.
        //    The fuzzer supplies a raw address (EOA) that will always succeed on a low-level call.
        //    Therefore the reference contract will complete without revert and return true.
        //    The buggy version will return false, violating the rule that a non-reverting call returns true.
        //    We deploy a minimal helper that always succeeds to model the adversarial party,
        //    because a raw fuzzed address is an EOA (no code), which SUCCEEDS and returns empty data,
        //    which is sufficient for the reference to return true. EOA behavior actually works here,
        //    but contract address behavior is also tolerable. We will use an increased gas limit if needed.
        //    Actually, low-level calls to EOAs succeed, and `transferFrom` selector might not exist,
        //    but the contract only checks `bool _s`. For EOAs, `call` succeeds (s=true).
        //    So we can let the fuzzer directly provide caddress as an EOA; it fulfills the adversarial party requirement.
        //    No helper deployment is strictly required.
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool returned) {
            ok = returned;
        } catch {
            ok = false;
        }
        // 3. Assert: if the call does not revert, the return value must be true.
        assertTrue(!ok || ok == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        bool ok;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
        }
        if (ok) {
            // All calls succeeded, so the last external call also succeeded.
            // The reference returns true, the bug returns false.
            assertTrue(ret);
        }
    }
}
